roles.source:
@startuml
layout horizontal
class Client
class Context {
  - strategy: Strategy
  + contextInterface()
  + setStrategy(strategy)
}
interface Strategy {
  + algorithmInterface()
}
class ConcreteStrategy {
  + algorithmInterface()
}
Client ..> Context : configures
Client ..> ConcreteStrategy : creates
Context o--> "1" Strategy : strategy
ConcreteStrategy ..|> Strategy
@enduml

solution.source:
@startuml
class Expense {
  - total
  - people
  - strategy: SplitStrategy
  + shares()
  + label()
  + setStrategy(strategy)
}
interface SplitStrategy {
  + split(total, people)
  + label()
}
class EqualSplit
class PercentSplit {
  - percents
}
class BirthdaySplit {
  - guest
}
Expense o--> "1" SplitStrategy : strategy
EqualSplit ..|> SplitStrategy
PercentSplit ..|> SplitStrategy
BirthdaySplit ..|> SplitStrategy
BirthdaySplit ..> EqualSplit : reuses
@enduml
